1	package ruth
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"sync"
8		"time"
9	
10		"github.com/gravitational/teleport/api/client"
11		"github.com/gravitational/teleport/api/types"
12		"golang.org/x/sync/errgroup"
13	
14		"ruth/ai"
15		"ruth/jira"
16		"ruth/reputation"
17		"ruth/risk"
18		"ruth/telemetry"
19	)
20	
21	type App struct {
22		cfg    *Config
23		tele   *client.Client
24		ai     ai.Provider
25		jira   *jira.Client
26		scorer *risk.Scorer
27		rep    *reputation.Store
28		meter  *telemetry.Meter
29	
30		pending   map[string]string
31		pendingMu sync.Mutex
32	}
33	
34	func NewApp(ctx context.Context, cfg *Config) (*App, error) {
35		tele, err := client.New(ctx, client.Config{
36			Addrs: []string{cfg.Teleport.Addr},
37			Credentials: []client.Credentials{
38				client.LoadIdentityFile(cfg.Teleport.IdentityFile),
39			},
40		})
41		if err != nil {
42			return nil, fmt.Errorf("teleport client: %w", err)
43		}
44	
45		prov, err := ai.New(cfg.AI)
46		if err != nil {
47			return nil, fmt.Errorf("ai provider: %w", err)
48		}
49	
50		jc, err := jira.New(cfg.Jira)
51		if err != nil {
52			return nil, fmt.Errorf("jira client: %w", err)
53		}
54	
55		scorer, err := risk.NewScorer(cfg.Risk)
56		if err != nil {
57			return nil, fmt.Errorf("scorer: %w", err)
58		}
59	
60		store, err := reputation.NewStore(cfg.Reputation)
61		if err != nil {
62			return nil, fmt.Errorf("reputation store: %w", err)
63		}
64	
65		var meter *telemetry.Meter
66		if cfg.Telemetry.Enabled {
67			meter, err = telemetry.New(ctx, cfg.Telemetry, store)
68			if err != nil {
69				return nil, fmt.Errorf("telemetry: %w", err)
70			}
71		}
72	
73		return &App{
74			cfg:     cfg,
75			tele:    tele,
76			ai:      prov,
77			jira:    jc,
78			scorer:  scorer,
79			rep:     store,
80			meter:   meter,
81			pending: map[string]string{},
82		}, nil
83	}
84	
85	// Close flushes outstanding telemetry. Safe to call even if telemetry
86	// is disabled.
87	func (a *App) Close(ctx context.Context) error {
88		return a.meter.Shutdown(ctx)
89	}
90	
91	func (a *App) Run(ctx context.Context) error {
92		slog.Info("ruth starting",
93			"provider", a.cfg.AI.Provider,
94			"threshold", a.cfg.Risk.TicketThreshold,
95			"itsm_project", a.cfg.Jira.Project,
96			"dry_run", a.cfg.DryRun)
97		if a.cfg.DryRun {
98			slog.Warn("dry-run enabled: no Teleport reviews or Jira tickets will be submitted")
99		}
100	
101		if err := a.rehydrate(ctx); err != nil {
102			return fmt.Errorf("rehydrate open ITSM tickets: %w", err)
103		}
104	
105		// Run watcher/poller under their own cancelable context rather than
106		// bolting them directly to the signal context. A coordinator
107		// goroutine waits for the signal, then sleeps for
108		// telemetry.shutdown_grace before cancelling the errgroup so that
109		// the OTel periodic reader can finish an in-flight export cleanly.
110		runCtx, cancelRun := context.WithCancel(context.Background())
111		defer cancelRun()
112		g, gctx := errgroup.WithContext(runCtx)
113		g.Go(func() error { return a.watchRequests(gctx) })
114		g.Go(func() error { return a.pollITSM(gctx) })
115		g.Go(func() error {
116			select {
117			case <-ctx.Done():
118				grace := time.Duration(0)
119				if a.cfg.Telemetry.Enabled {
120					grace = a.cfg.Telemetry.ShutdownGrace
121				}
122				if grace > 0 {
123					slog.Info("shutdown signal received; waiting for telemetry flush", "grace", grace)
124					select {
125					case <-time.After(grace):
126					case <-gctx.Done():
127						// errgroup collapsed for some other reason; stop waiting.
128					}
129				}
130				cancelRun()
131			case <-gctx.Done():
132			}
133			return nil
134		})
135	
136		return g.Wait()
137	}
138	
139	func (a *App) rehydrate(ctx context.Context) error {
140		open, err := a.jira.ListOpenTeleportTickets(ctx)
141		if err != nil {
142			return err
143		}
144		a.pendingMu.Lock()
145		for reqID, ticket := range open {
146			a.pending[reqID] = ticket
147		}
148		a.pendingMu.Unlock()
149		slog.Info("rehydrated pending tickets", "count", len(open))
150		return nil
151	}
152	
153	func (a *App) watchRequests(ctx context.Context) error {
154		watcher, err := a.tele.NewWatcher(ctx, types.Watch{
155			Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
156		})
157		if err != nil {
158			return fmt.Errorf("start watcher: %w", err)
159		}
160		defer watcher.Close()
161	
162		for {
163			select {
164			case <-ctx.Done():
165				return ctx.Err()
166			case <-watcher.Done():
167				return watcher.Error()
168			case ev := <-watcher.Events():
169				if ev.Type != types.OpPut {
170					continue
171				}
172				req, ok := ev.Resource.(types.AccessRequest)
173				if !ok {
174					continue
175				}
176				if req.GetState() != types.RequestState_PENDING {
177					continue
178				}
179				if !a.reserveOrSkip(req.GetName()) {
180					continue
181				}
182				go a.handleRequest(ctx, req)
183			}
184		}
185	}
186	
187	// reserveOrSkip atomically claims a slot for request id. Returns true if
188	// this caller won the race and should process the request; false if the
189	// id is already in flight or already has a ticket. Using the same map
190	// for both reservations and ticket mappings keeps dedup decisions on a
191	// single source of truth.
192	func (a *App) reserveOrSkip(id string) bool {
193		a.pendingMu.Lock()
194		defer a.pendingMu.Unlock()
195		if _, held := a.pending[id]; held {
196			return false
197		}
198		a.pending[id] = ""
199		return true
200	}
201	
202	func (a *App) releasePending(id string) {
203		a.pendingMu.Lock()
204		defer a.pendingMu.Unlock()
205		delete(a.pending, id)
206	}
207	
208	func (a *App) recordTicket(id, ticket string) {
209		a.pendingMu.Lock()
210		defer a.pendingMu.Unlock()
211		a.pending[id] = ticket
212	}
213	
214	func (a *App) handleRequest(ctx context.Context, req types.AccessRequest) {
215		id := req.GetName()
216		user := req.GetUser()
217		log := slog.With("request_id", id, "user", user)
218	
219		// Release the reservation unless we successfully record a ticket;
220		// that way score/Jira failures are re-tryable on the next OpPut and
221		// auto-approved requests don't leave stale entries behind.
222		handled := false
223		defer func() {
224			if !handled {
225				a.releasePending(id)
226			}
227		}()
228	
229		log.Info("scoring access request")
230		result, err := a.scorer.Score(ctx, a.ai, req)
231		if err != nil {
232			log.Error("scoring failed", "err", err)
233			return
234		}
235		log.Info("risk scored",
236			"score", result.Score,
237			"tier", result.Tier.Name,
238			"components", result.Components)
239	
240		assessment, err := a.rep.Assess(ctx, user, result.Components)
241		if err != nil {
242			log.Warn("reputation update failed", "err", err)
243		}
244		if len(assessment.Penalties) > 0 {
245			reasons := make([]string, 0, len(assessment.Penalties))
246			for _, p := range assessment.Penalties {
247				reasons = append(reasons, p.Reason)
248			}
249			log.Info("reputation docked",
250				"previous", assessment.Previous,
251				"current", assessment.Score,
252				"reasons", reasons)
253		}
254	
255		threshold := a.cfg.Risk.TicketThreshold
256		if result.Escalation {
257			threshold = a.cfg.Risk.EscalationThresholdFor(req.GetRoles())
258			log.Info("session escalation detected", "threshold", threshold)
259		}
260	
261		if result.Score < threshold {
262			reason := fmt.Sprintf("ruth: %s (score %d) — auto-approved",
263				result.Tier.Name, result.Score)
264			if err := a.submitReview(ctx, id, types.RequestState_APPROVED, reason); err != nil {
265				log.Error("auto-approve failed", "err", err)
266				return
267			}
268			log.Info("access request auto-approved",
269				"score", result.Score,
270				"tier", result.Tier.Name,
271				"threshold", threshold)
272			return
273		}
274	
275		if a.cfg.DryRun {
276			log.Info("dry-run: would create ITSM ticket and hold request pending",
277				"score", result.Score,
278				"tier", result.Tier.Name,
279				"threshold", threshold)
280			return
281		}
282	
283		ticket, err := a.jira.CreateITSMTicket(ctx, jira.TicketInput{
284			RequestID:   id,
285			User:        req.GetUser(),
286			Roles:       req.GetRoles(),
287			Reason:      req.GetRequestReason(),
288			Score:       result.Score,
289			Tier:        result.Tier.Name,
290			Components:  result.Components,
291			AIReasoning: result.Reasoning,
292			Escalation:  result.Escalation,
293		})
294		if err != nil {
295			log.Error("create ITSM ticket failed", "err", err)
296			return
297		}
298	
299		a.recordTicket(id, ticket)
300		handled = true
301		log.Info("ITSM ticket created, request held for SRE review",
302			"ticket", ticket, "tier", result.Tier.Name)
303	}
304	
305	func (a *App) pollITSM(ctx context.Context) error {
306		t := time.NewTicker(a.cfg.Jira.PollInterval)
307		defer t.Stop()
308		for {
309			select {
310			case <-ctx.Done():
311				return ctx.Err()
312			case <-t.C:
313				a.reconcileITSM(ctx)
314			}
315		}
316	}
317	
318	func (a *App) reconcileITSM(ctx context.Context) {
319		a.pendingMu.Lock()
320		snap := make(map[string]string, len(a.pending))
321		for k, v := range a.pending {
322			snap[k] = v
323		}
324		a.pendingMu.Unlock()
325	
326		for requestID, ticket := range snap {
327			if ticket == "" {
328				// Reservation for an in-flight handleRequest; nothing to poll yet.
329				continue
330			}
331			status, err := a.jira.TicketStatus(ctx, ticket)
332			if err != nil {
333				slog.Warn("ITSM status check failed", "ticket", ticket, "err", err)
334				continue
335			}
336			var next types.RequestState
337			switch status {
338			case jira.StatusApproved:
339				next = types.RequestState_APPROVED
340			case jira.StatusRejected:
341				next = types.RequestState_DENIED
342			default:
343				continue
344			}
345			reason := fmt.Sprintf("ruth: ITSM %s resolved (%s)", ticket, status)
346			if err := a.submitReview(ctx, requestID, next, reason); err != nil {
347				slog.Error("submit review failed", "request_id", requestID, "err", err)
348				continue
349			}
350			a.pendingMu.Lock()
351			delete(a.pending, requestID)
352			a.pendingMu.Unlock()
353		}
354	}
355	
356	func (a *App) submitReview(ctx context.Context, requestID string, state types.RequestState, reason string) error {
357		if a.cfg.DryRun {
358			slog.Info("dry-run: skipping AccessReview submission",
359				"request_id", requestID,
360				"state", state.String(),
361				"reason", reason)
362			return nil
363		}
364		_, err := a.tele.SubmitAccessReview(ctx, types.AccessReviewSubmission{
365			RequestID: requestID,
366			Review: types.AccessReview{
367				Author:        "ruth",
368				ProposedState: state,
369				Reason:        reason,
370			},
371		})
372		return err
373	}
